class SISSLLivenessServiceTests(TestCase):
    def setUp(self):
        self.user = _make_user()

    def _liveness(self):
        from api.users.services.kyc_services.sissl_service import SISSLServices

        return SISSLServices.liveness(user=self.user, photo="https://example.com/selfie.jpg")

    def test_pass_above_threshold_persists_score_and_passes(self, provider, *_):
        provider.return_value.liveness.return_value = {"passes": True, "score": 92}

        result = self._liveness()

        self.assertTrue(result.is_real)
        self.user.refresh_from_db()
        self.assertEqual(self.user.liveness_score, 92.0)
        self.assertTrue(self.user.liveness_passes)

    def test_score_below_threshold_fails_and_persists_failure(self, provider, *_):
        provider.return_value.liveness.return_value = {"passes": True, "score": 50}

        with self.assertRaises(SISSLLivenessFailed):
            self._liveness()

        self.user.refresh_from_db()
        self.assertEqual(self.user.liveness_score, 50.0)
        self.assertFalse(self.user.liveness_passes)

    def test_documented_result_key_passes_end_to_end(self, provider, *_):
        """Regression: with only `passes`/`live` read, a vendor response using
        the documented `result: "real"` spelling failed every check even at a
        perfect score."""
        provider.return_value.liveness.return_value = {"result": "real", "score": 92}

        result = self._liveness()

        self.assertTrue(result.is_real)
        self.user.refresh_from_db()
        self.assertTrue(self.user.liveness_passes)

    def test_documented_fake_result_fails(self, provider, *_):
        provider.return_value.liveness.return_value = {"result": "fake", "score": 92}

        with self.assertRaises(SISSLLivenessFailed):
            self._liveness()

        self.user.refresh_from_db()
        self.assertFalse(self.user.liveness_passes)

    def test_unrecognised_response_shape_fails_closed(self, provider, *_):
        """A response we cannot read must never pass an identity check."""
        provider.return_value.liveness.return_value = {"score": 99, "confidence": "high"}

        with self.assertRaises(SISSLLivenessFailed):
            self._liveness()

        self.user.refresh_from_db()
        self.assertFalse(self.user.liveness_passes)

    def test_vendor_error_keeps_previous_result(self, provider, *_):
        self.user.liveness_score = 90.0
        self.user.liveness_passes = True
        self.user.save()
        provider.return_value.liveness.side_effect = SISSLError("down")

        with self.assertRaises(SISSLError):
            self._liveness()

        self.user.refresh_from_db()
        self.assertEqual(self.user.liveness_score, 90.0)
        self.assertTrue(self.user.liveness_passes)


class SisslProviderErrorTranslationTests(TestCase):
    """
    `SisslProvider._post` error translation — the layer that decides what a
    non-2xx from the vendor becomes on our side.

    Regression cover for a production incident: SISSL answered
    `401 {"message": "Unauthenticated."}` because our API token had been
    revoked, and that wording was forwarded verbatim to the end user as a
    503. Users (and the client code) read it as their OWN session being dead.
    """

    def _provider_returning(self, *, status_code, body, content_type="application/json"):
        from api.users.services.kyc_services.sissl_service import SisslProvider

        response = Mock()
        response.status_code = status_code
        response.headers = {"Content-Type": content_type}
        response.text = json.dumps(body) if isinstance(body, dict) else body
        if isinstance(body, dict):
            response.json = Mock(return_value=body)
        else:
            # A non-JSON body must raise on .json(), the way requests does.
            response.json = Mock(side_effect=ValueError("no json"))

        session = Mock()
        session.post.return_value = response
        return SisslProvider(base_url="https://vendor.test", api_token="tok", session=session)

    def test_vendor_401_raises_auth_error_without_leaking_vendor_wording(self):
        provider = self._provider_returning(status_code=401, body={"message": "Unauthenticated."})

        with self.assertRaises(SISSLAuthError) as ctx:
            provider.liveness({"photo": "https://example.com/selfie.jpg"})

        self.assertNotIn("Unauthenticated", str(ctx.exception))
        self.assertEqual(
            str(ctx.exception),
            "Verification service is temporarily unavailable. Please try again.",
        )

    def test_vendor_403_also_raises_auth_error(self):
        provider = self._provider_returning(status_code=403, body={"message": "This action is unauthorized."})

        with self.assertRaises(SISSLAuthError):
            provider.liveness({"photo": "https://example.com/selfie.jpg"})

    def test_bare_401_with_no_json_body_is_still_an_auth_error(self):
        """A gateway in front of SISSL can refuse the call with plain text.
        Classification keys off the status code, never off parsing the body."""
        provider = self._provider_returning(
            status_code=401, body="Unauthorized", content_type="text/plain"
        )

        with self.assertRaises(SISSLAuthError):
            provider.liveness({"photo": "x"})

    def test_auth_error_is_catchable_as_sissl_error(self):
        """The service layer's audit-and-reraise blocks catch SISSLError, so
        the subclass must not slip past them."""
        provider = self._provider_returning(status_code=401, body={"message": "Unauthenticated."})

        with self.assertRaises(SISSLError):
            provider.liveness({"photo": "https://example.com/selfie.jpg"})

    def test_vendor_422_on_a_bad_image_is_invalid_input_not_an_outage(self):
        """Observed live: SISSL answers 422 "There are some issues with the
        image". The user can retake the photo, so this must not surface as a
        vendor outage telling them to wait."""
        provider = self._provider_returning(
            status_code=422, body={"message": "There are some issues with the image"}
        )

        with self.assertRaises(SISSLInvalidInput) as ctx:
            provider.liveness({"photo": "x"})

        # The vendor's wording is actionable here, unlike "Unauthenticated."
        self.assertEqual(str(ctx.exception), "There are some issues with the image")

    def test_vendor_400_is_also_invalid_input(self):
        provider = self._provider_returning(status_code=400, body={"message": "id is invalid"})

        with self.assertRaises(SISSLInvalidInput):
            provider.bvn_verification({"id": "nope"})

    def test_invalid_input_is_catchable_as_sissl_error(self):
        """The service layer's audit-and-reraise blocks catch SISSLError."""
        provider = self._provider_returning(status_code=422, body={"message": "bad"})

        with self.assertRaises(SISSLError):
            provider.liveness({"photo": "x"})

    def test_invalid_input_is_not_confused_with_auth_failure(self):
        provider = self._provider_returning(status_code=422, body={"message": "bad"})

        with self.assertRaises(SISSLInvalidInput) as ctx:
            provider.liveness({"photo": "x"})

        self.assertNotIsInstance(ctx.exception, SISSLAuthError)

    def test_other_non_2xx_still_raises_plain_sissl_error_with_vendor_message(self):
        """Only 401/403 and 400/422 are reclassified. A vendor 500 is a real
        upstream fault and keeps the generic SISSLError -> 503 path, with the
        vendor's detail preserved for the logs."""
        provider = self._provider_returning(status_code=500, body={"message": "internal error"})

        with self.assertRaises(SISSLError) as ctx:
            provider.liveness({"photo": "x"})

        self.assertNotIsInstance(ctx.exception, SISSLAuthError)
        self.assertNotIsInstance(ctx.exception, SISSLInvalidInput)
        self.assertEqual(str(ctx.exception), "internal error")

    def test_html_outage_page_is_not_classified_as_auth(self):
        provider = self._provider_returning(
            status_code=503,
            body="<html><body>502 Bad Gateway</body></html>",
            content_type="text/html; charset=utf-8",
        )

        with self.assertRaises(SISSLError) as ctx:
            provider.liveness({"photo": "x"})

        self.assertNotIsInstance(ctx.exception, SISSLAuthError)
        self.assertNotIn("<html>", str(ctx.exception))


class LivenessVerdictParsingTests(TestCase):
    """
    Which key carries SISSL's live/not-live verdict.

    The provider docstring documents `result: "real" | "fake"`, while the
    payloads this code was written against carried `passes`/`live` — and the
    original implementation read only the latter two. If the vendor actually
    sends `result`, reading only `passes`/`live` yields None for every
    response and fails every check regardless of score, which is
    indistinguishable from "all our users take bad selfies".
    """

    def _verdict(self, raw):
        from api.users.services.kyc_services.sissl_service import _liveness_verdict

        return _liveness_verdict(raw)

    def test_reads_passes_key(self):
        self.assertIs(self._verdict({"passes": True, "score": 92}), True)
        self.assertIs(self._verdict({"passes": False, "score": 92}), False)

    def test_reads_live_key(self):
        self.assertIs(self._verdict({"live": True, "score": 92}), True)
        self.assertIs(self._verdict({"live": False, "score": 92}), False)

    def test_reads_documented_result_key(self):
        """The spelling the provider docstring actually documents."""
        self.assertIs(self._verdict({"result": "real", "score": 92}), True)
        self.assertIs(self._verdict({"result": "fake", "score": 92}), False)

    def test_result_matching_is_case_and_whitespace_insensitive(self):
        self.assertIs(self._verdict({"result": "  REAL "}), True)

    def test_explicit_false_is_not_overridden_by_a_later_spelling(self):
        """Key presence wins over truthiness — an explicit `passes: false`
        is a real "not live", not a reason to go looking for another key."""
        self.assertIs(self._verdict({"passes": False, "result": "real"}), False)

    def test_unrecognised_shape_returns_none_so_callers_fail_closed(self):
        self.assertIsNone(self._verdict({"score": 99, "confidence": "high"}))
        self.assertIsNone(self._verdict({}))


class ErrorEnvelopeStatusClassificationTests(TestCase):
    """`_error_for_status` must not label server faults as client errors."""

    def test_5xx_statuses_are_typed_as_server_errors(self):
        from shared.response.error import _error_for_status

        for code in (500, 502, 503, 504):
            with self.subTest(status=code):
                self.assertEqual(_error_for_status(code, "boom")["type"], "server_error")

    def test_unmapped_5xx_defaults_to_server_error(self):
        from shared.response.error import _error_for_status

        self.assertEqual(_error_for_status(507, "boom")["type"], "server_error")

    def test_unmapped_4xx_still_defaults_to_client_error(self):
        from shared.response.error import _error_for_status

        self.assertEqual(_error_for_status(429, "slow down")["type"], "client_error")

    def test_known_codes_keep_their_existing_classification(self):
        from shared.response.error import _error_for_status

        self.assertEqual(_error_for_status(400, "x")["code"], "invalid")
        self.assertEqual(_error_for_status(401, "x")["code"], "not_authenticated")
        self.assertEqual(_error_for_status(404, "x")["code"], "not_found")


class SISSLLivenessRateLimitTests(TestCase):
    """
    The liveness cost-discipline guard itself — `_enforce_liveness_rate_limit`
    is patched out of SISSLLivenessServiceTests, so the limiter's own behavior
    is verified here against a mocked Redis counter. Excess attempts must fail
    BEFORE the vendor call is made.
    """

    cap = 2

    def setUp(self):
        from api.users.services.kyc_services.sissl_service import SISSLServices

        self.SISSLServices = SISSLServices
        self.user = _make_user()

    @patch("api.users.services.kyc_services.sissl_service.SISSL_LIVENESS_HOURLY_CAP", 2)
    @patch("api.users.services.kyc_services.sissl_service.RedisService._atomic_increment")
    @patch("api.users.services.kyc_services.sissl_service.log_activity")
    @patch("api.users.services.kyc_services.sissl_service.SISSLServices._liveness_threshold", return_value=80)
    @patch("api.users.services.kyc_services.sissl_service.SISSLServices._provider")
    def test_attempt_over_the_hourly_cap_fails_before_the_vendor_call(self, provider, threshold, _activity, incr):
        incr.return_value = (self.cap + 1, 3600)  # third call of the hour

        with self.assertRaises(SISSLError):
            self.SISSLServices.liveness(user=self.user, photo="https://example.com/selfie.jpg")

        incr.assert_called_once_with(f"sissl:liveness:{self.user.id}", 3600)
        provider.return_value.liveness.assert_not_called()
        self.user.refresh_from_db()
        self.assertIsNone(self.user.liveness_score)

    @patch("api.users.services.kyc_services.sissl_service.SISSL_LIVENESS_HOURLY_CAP", 2)
    @patch("api.users.services.kyc_services.sissl_service.RedisService._atomic_increment")
    @patch("api.users.services.kyc_services.sissl_service.log_activity")
    @patch("api.users.services.kyc_services.sissl_service.SISSLServices._liveness_threshold", return_value=80)
    @patch("api.users.services.kyc_services.sissl_service.SISSLServices._provider")
    def test_attempt_under_the_hourly_cap_reaches_the_vendor(self, provider, threshold, _activity, incr):
        incr.return_value = (1, 3600)  # first call of the hour
        provider.return_value.liveness.return_value = {"passes": True, "score": 92}

        result = self.SISSLServices.liveness(user=self.user, photo="https://example.com/selfie.jpg")

        self.assertTrue(result.is_real)
        provider.return_value.liveness.assert_called_once()

    @patch("api.users.services.kyc_services.sissl_service.log_activity")
    @patch("api.users.services.kyc_services.sissl_service.SISSLServices._liveness_threshold", return_value=80)
    @patch("api.users.services.kyc_services.sissl_service.SISSLServices._provider")
    @patch("api.users.services.kyc_services.sissl_service.RedisService._atomic_increment")
    def test_system_calls_are_not_rate_limited(self, incr, provider, threshold, _activity):
        provider.return_value.liveness.return_value = {"passes": True, "score": 92}

        result = self.SISSLServices.liveness(user=None, photo="https://example.com/selfie.jpg")

        self.assertTrue(result.is_real)
        incr.assert_not_called()
        provider.return_value.liveness.assert_called_once()


class LivenessAvatarSettingViewTests(APITestCase):
    endpoint_template = "/api/v1/users/kyc/set-avatar/{}/"

    def setUp(self):
        self.admin = _make_user(role=UserRole.ADMIN)
        self.target_user = _make_user(liveness_selfie="https://example.com/verified-selfie.jpg")
        self.endpoint = self.endpoint_template.format(self.target_user.id)
        self.client.force_authenticate(self.admin)

    def test_requires_authentication(self):
        self.client.force_authenticate(user=None)

        response = self.client.post(self.endpoint)

        self.assertEqual(response.status_code, status.HTTP_401_UNAUTHORIZED)

    def test_requires_admin_or_super_admin_role(self):
        creator = _make_user(role=UserRole.COURSE_CREATOR)
        self.client.force_authenticate(creator)

        response = self.client.post(self.endpoint)

        self.assertEqual(response.status_code, status.HTTP_403_FORBIDDEN)

    def test_returns_not_found_for_unknown_target_user(self):
        response = self.client.post(self.endpoint_template.format(uuid4()))

        self.assertEqual(response.status_code, status.HTTP_404_NOT_FOUND)

    def test_returns_bad_request_when_target_has_no_liveness_selfie(self):
        self.target_user.liveness_selfie = ""
        self.target_user.save(update_fields=["liveness_selfie"])

        response = self.client.post(self.endpoint)

        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)
        self.assertIn("does not have a liveness selfie", response.data["errors"][0]["message"])

    @patch("api.users.views.kyc_views.client_meta", return_value=("203.0.113.10", "test-agent"))
    def test_sets_target_liveness_selfie_as_avatar(self, client_meta):
        response = self.client.post(self.endpoint)

        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertEqual(response.data["message"], "Profile picture set successfully.")
        self.assertEqual(
            response.data["data"]["avatar_url"],
            "https://example.com/verified-selfie.jpg",
        )
        self.target_user.refresh_from_db()
        self.assertEqual(self.target_user.avatar_url, self.target_user.liveness_selfie)
        client_meta.assert_called_once()

    @patch(
        "api.users.views.kyc_views.SISSLServices.set_profile_picture",
        side_effect=RuntimeError("avatar storage failed"),
    )
    def test_returns_bad_request_when_setting_avatar_fails(self, set_profile_picture):
        response = self.client.post(self.endpoint)

        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)
        self.assertIn("avatar storage failed", response.data["errors"][0]["message"])
        set_profile_picture.assert_called_once()


class UserAdminServiceTests(TestCase):
    def setUp(self):
        self.admin = _make_user(email="admin@example.com", role=UserRole.ADMIN)
        self.creator = _make_user(
            email="creator-mod@example.com",
            role=UserRole.COURSE_CREATOR,
            status=AccountStatus.ACTIVE,
        )

    def test_suspend_sets_suspended_status_and_deactivates(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Plagiarism."
        )

        self.creator.refresh_from_db()
        self.assertEqual(self.creator.status, AccountStatus.SUSPENDED)
        self.assertFalse(self.creator.is_active)

    def test_suspend_is_the_only_path_that_produces_suspended(self):
        """Regression: SUSPENDED was previously unreachable - login and token
        refresh rejected it but nothing could ever assign it."""

        self.assertFalse(User.objects.filter(status=AccountStatus.SUSPENDED).exists())

        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Spam."
        )

        self.assertTrue(User.objects.filter(status=AccountStatus.SUSPENDED).exists())

    def test_suspend_notifies_the_account_holder_with_the_reason(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Repeated plagiarism."
        )

        notification = Notification.objects.filter(receiver=self.creator).first()
        self.assertIsNotNone(notification)
        self.assertIn("Repeated plagiarism.", notification.content)

    def test_suspend_logs_activity_against_the_acting_admin(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Spam."
        )

        entry = UserActivityLog.objects.filter(
            user=self.admin,
            action=UserActivityActionEnums.ACCOUNT_SUSPENDED,
        ).first()
        self.assertIsNotNone(entry)
        self.assertEqual(entry.details["target_email"], self.creator.email)

    def test_cannot_suspend_twice(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Spam."
        )

        with self.assertRaises(ValidationError):
            user_admin_service.suspend_user(
                actor=self.admin, user=self.creator, reason="Spam again."
            )

    def test_cannot_suspend_own_account(self):
        with self.assertRaises(ValidationError):
            user_admin_service.suspend_user(
                actor=self.admin, user=self.admin, reason="Oops."
            )

    def test_cannot_suspend_another_admin(self):
        peer = _make_user(email="peer-admin@example.com", role=UserRole.ADMIN)

        with self.assertRaises(ValidationError) as ctx:
            user_admin_service.suspend_user(
                actor=self.admin, user=peer, reason="Disagreement."
            )

        # Pins the wording, which is also what the OpenAPI example promises -
        # and catches naive verb suffixing ("suspendd").
        self.assertIn(
            "You cannot suspend an admin or super admin account here.",
            str(ctx.exception),
        )

    def test_cannot_suspend_the_super_admin(self):
        owner = _make_user(email="owner@example.com", role=UserRole.SUPER_ADMIN)

        with self.assertRaises(ValidationError):
            user_admin_service.suspend_user(
                actor=self.admin, user=owner, reason="Coup."
            )

    def test_non_admin_actor_is_rejected(self):
        other_creator = _make_user(
            email="other-creator@example.com", role=UserRole.COURSE_CREATOR
        )

        with self.assertRaises(PermissionDenied):
            user_admin_service.suspend_user(
                actor=other_creator, user=self.creator, reason="Nope."
            )

    def test_reinstate_restores_active_status(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Spam."
        )

        user_admin_service.reinstate_user(actor=self.admin, user=self.creator)

        self.creator.refresh_from_db()
        self.assertEqual(self.creator.status, AccountStatus.ACTIVE)
        self.assertTrue(self.creator.is_active)

    def test_reinstate_rejects_an_account_that_was_never_suspended(self):
        with self.assertRaises(ValidationError):
            user_admin_service.reinstate_user(actor=self.admin, user=self.creator)

    def test_reinstate_rejects_an_unaccepted_invitee(self):
        invitee = _make_user(
            email="invitee-mod@example.com", role=UserRole.COURSE_CREATOR
        )
        invitee.set_unusable_password()
        invitee.status = AccountStatus.DEACTIVATED
        invitee.is_active = False
        invitee.save(update_fields=["password", "status", "is_active"])

        with self.assertRaises(ValidationError):
            user_admin_service.reinstate_user(actor=self.admin, user=invitee)

    def test_deactivate_then_reinstate_round_trips(self):
        user_admin_service.deactivate_user(
            actor=self.admin, user=self.creator, reason="Closed at own request."
        )
        self.creator.refresh_from_db()
        self.assertEqual(self.creator.status, AccountStatus.DEACTIVATED)

        user_admin_service.reinstate_user(actor=self.admin, user=self.creator)
        self.creator.refresh_from_db()
        self.assertEqual(self.creator.status, AccountStatus.ACTIVE)


class UserAdminApiTests(APITestCase):
    def setUp(self):
        self.admin = _make_user(email="api-admin@example.com", role=UserRole.ADMIN)
        self.creator = _make_user(
            email="api-creator@example.com",
            role=UserRole.COURSE_CREATOR,
            status=AccountStatus.ACTIVE,
        )

    def test_list_requires_authentication(self):
        response = self.client.get("/api/v1/users/admin/")
        self.assertEqual(response.status_code, status.HTTP_401_UNAUTHORIZED)

    def test_creator_cannot_list_users(self):
        self.client.force_authenticate(self.creator)

        response = self.client.get("/api/v1/users/admin/")
        self.assertEqual(response.status_code, status.HTTP_403_FORBIDDEN)

    def test_admin_lists_public_creators_not_just_staff(self):
        self.client.force_authenticate(self.admin)

        response = self.client.get("/api/v1/users/admin/")
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        emails = [row["email"] for row in response.data["data"]["results"]]
        self.assertIn(self.creator.email, emails)

    def test_admin_can_search_by_email(self):
        self.client.force_authenticate(self.admin)

        response = self.client.get("/api/v1/users/admin/", {"search": "api-creator"})
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertEqual(len(response.data["data"]["results"]), 1)

    def test_admin_can_filter_by_status(self):
        self.client.force_authenticate(self.admin)

        response = self.client.get("/api/v1/users/admin/", {"status": "ACTIVE"})
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        for row in response.data["data"]["results"]:
            self.assertEqual(row["status"], "ACTIVE")

    def test_suspend_endpoint_suspends_and_returns_new_status(self):
        self.client.force_authenticate(self.admin)

        response = self.client.post(
            f"/api/v1/users/admin/{self.creator.id}/suspend/",
            {"reason": "Repeated plagiarism."},
            format="json",
        )
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertEqual(response.data["status"], "SUSPENDED")
        self.assertFalse(response.data["is_active"])

    def test_suspend_requires_a_reason(self):
        self.client.force_authenticate(self.admin)

        response = self.client.post(
            f"/api/v1/users/admin/{self.creator.id}/suspend/", {}, format="json"
        )
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)

    def test_suspended_user_cannot_log_in(self):
        self.client.force_authenticate(self.admin)
        self.client.post(
            f"/api/v1/users/admin/{self.creator.id}/suspend/",
            {"reason": "Spam."},
            format="json",
        )
        self.client.force_authenticate(None)

        response = self.client.post(
            "/api/v1/auth/login/",
            {"email": self.creator.email, "password": "testpass123"},
            format="json",
        )
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)

    def test_reinstated_user_can_log_in_again(self):
        self.client.force_authenticate(self.admin)
        self.client.post(
            f"/api/v1/users/admin/{self.creator.id}/suspend/",
            {"reason": "Spam."},
            format="json",
        )
        self.client.post(
            f"/api/v1/users/admin/{self.creator.id}/reinstate/", {}, format="json"
        )
        self.client.force_authenticate(None)

        response = self.client.post(
            "/api/v1/auth/login/",
            {"email": self.creator.email, "password": "testpass123"},
            format="json",
        )
        self.assertEqual(response.status_code, status.HTTP_200_OK)

    def test_creator_cannot_suspend_anyone(self):
        victim = _make_user(email="victim@example.com", role=UserRole.COURSE_CREATOR)
        self.client.force_authenticate(self.creator)

        response = self.client.post(
            f"/api/v1/users/admin/{victim.id}/suspend/",
            {"reason": "Because."},
            format="json",
        )
        self.assertEqual(response.status_code, status.HTTP_403_FORBIDDEN)


class AdminActivityLogApiTests(APITestCase):
    def setUp(self):
        self.admin = _make_user(email="log-admin@example.com", role=UserRole.ADMIN)
        self.creator = _make_user(
            email="log-creator@example.com", role=UserRole.COURSE_CREATOR
        )

    def test_creator_cannot_read_the_platform_wide_log(self):
        self.client.force_authenticate(self.creator)

        response = self.client.get("/api/v1/users/activity-log/")
        self.assertEqual(response.status_code, status.HTTP_403_FORBIDDEN)

    def test_admin_sees_another_users_entries(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Spam."
        )
        self.client.force_authenticate(self.admin)

        response = self.client.get(
            "/api/v1/users/activity-log/", {"user": str(self.admin.id)}
        )
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        actions = [row["action"] for row in response.data["data"]["results"]]
        self.assertIn(UserActivityActionEnums.ACCOUNT_SUSPENDED, actions)

    def test_self_scoped_log_still_only_shows_own_entries(self):
        user_admin_service.suspend_user(
            actor=self.admin, user=self.creator, reason="Spam."
        )
        self.client.force_authenticate(self.creator)

        response = self.client.get("/api/v1/users/me/activity-log/")
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        actions = [row["action"] for row in response.data["data"]["results"]]
        self.assertNotIn(UserActivityActionEnums.ACCOUNT_SUSPENDED, actions)


class CreateSuperuserTests(TestCase):
    """Regression cover for shell-created superusers.

    create_superuser used to leave `role` at its COURSE_CREATOR default while
    setting is_superuser=True. Because permission_service grants superusers every permission on
    that flag, the result was a full-authority account that reported itself as
    a public creator and escaped the one-seat unique index entirely.
    """

    def test_createsuperuser_assigns_the_super_admin_role(self):
        user = User.objects.create_superuser(
            email="shell-owner@example.com", password="testpass123"
        )

        self.assertEqual(user.role, UserRole.SUPER_ADMIN)
        self.assertEqual(user.status, AccountStatus.ACTIVE)
        self.assertTrue(user.is_staff)
        self.assertTrue(user.is_superuser)

    def test_second_createsuperuser_is_refused_with_a_readable_message(self):
        User.objects.create_superuser(
            email="shell-owner2@example.com", password="testpass123"
        )

        with self.assertRaises(ValueError) as ctx:
            User.objects.create_superuser(
                email="shell-owner3@example.com", password="testpass123"
            )

        self.assertIn("super admin already exists", str(ctx.exception).lower())

    def test_shell_superuser_no_longer_masquerades_as_a_course_creator(self):
        user = User.objects.create_superuser(
            email="shell-owner4@example.com", password="testpass123"
        )

        self.assertNotEqual(user.role, UserRole.COURSE_CREATOR)

    def test_explicit_role_is_still_honoured(self):
        """setdefault, not an override - a caller passing a role gets it."""

        user = User.objects.create_superuser(
            email="shell-admin@example.com",
            password="testpass123",
            role=UserRole.ADMIN,
        )

        self.assertEqual(user.role, UserRole.ADMIN)


class UnlockAccountCommandTests(TestCase):
    def setUp(self):
        self.user = _make_user(email="locked-out@example.com")
        self.user.failed_login_attempts = 5
        self.user.locked_until = timezone.now() + timedelta(minutes=15)
        self.user.save(update_fields=["failed_login_attempts", "locked_until"])

    def test_clears_the_lockout(self):
        call_command("unlock_account", "locked-out@example.com", stdout=StringIO())

        self.user.refresh_from_db()
        self.assertIsNone(self.user.locked_until)
        self.assertEqual(self.user.failed_login_attempts, 0)

    def test_is_case_insensitive_on_email(self):
        call_command("unlock_account", "LOCKED-OUT@EXAMPLE.COM", stdout=StringIO())

        self.user.refresh_from_db()
        self.assertIsNone(self.user.locked_until)

    def test_writes_an_activity_log_entry(self):
        call_command("unlock_account", "locked-out@example.com", stdout=StringIO())

        self.assertTrue(
            UserActivityLog.objects.filter(
                user=self.user,
                action=UserActivityActionEnums.LOCKOUT_CLEARED,
            ).exists()
        )

    def test_unknown_email_raises_command_error(self):
        with self.assertRaises(CommandError):
            call_command("unlock_account", "nobody@example.com", stdout=StringIO())

    def test_unlocked_account_is_a_no_op(self):
        call_command("unlock_account", "locked-out@example.com", stdout=StringIO())
        call_command("unlock_account", "locked-out@example.com", stdout=StringIO())

        self.assertEqual(
            UserActivityLog.objects.filter(
                user=self.user,
                action=UserActivityActionEnums.LOCKOUT_CLEARED,
            ).count(),
            1,
        )

    def test_unlocking_the_super_admin_is_possible(self):
        """The break-glass case: the seat cannot be moderated through any API
        route, so the command is the only way to clear its lockout early."""

        owner = _make_user(email="owner-locked@example.com", role=UserRole.SUPER_ADMIN)
        owner.locked_until = timezone.now() + timedelta(minutes=15)
        owner.save(update_fields=["locked_until"])

        call_command("unlock_account", "owner-locked@example.com", stdout=StringIO())

        owner.refresh_from_db()
        self.assertIsNone(owner.locked_until)
